CREATE TYPE "LaunchPlanStatus" AS ENUM ('ACTIVE', 'COMPLETE', 'ARCHIVED');
CREATE TYPE "LaunchStageKey" AS ENUM ('NICHE_APPROVED', 'SUPPLIER_SAMPLE', 'COMPLIANCE_VALIDATION', 'FINAL_COST', 'BRAND_TRADEMARK_READINESS', 'PACKAGING_ARTWORK', 'LISTING_ASSETS', 'KEYWORD_PLAN', 'INVENTORY_ORDER', 'SHIPMENT_FBA', 'LAUNCH_DATE', 'ADVERTISING_SETUP', 'RANK_MARKET_MONITORING', 'REVIEW_RETURNS_LEARNING');
CREATE TYPE "LaunchStageStatus" AS ENUM ('NOT_STARTED', 'IN_PROGRESS', 'BLOCKED', 'COMPLETE');
CREATE TABLE "launch_plans" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "project_id" TEXT NOT NULL, "name" TEXT NOT NULL, "status" "LaunchPlanStatus" NOT NULL DEFAULT 'ACTIVE', "evidence_snapshot" JSONB NOT NULL, "research_outputs" JSONB NOT NULL, "assumptions" JSONB NOT NULL, "risks" JSONB NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "launch_plans_pkey" PRIMARY KEY ("id"));
CREATE INDEX "launch_plans_project" ON "launch_plans"("organization_id", "project_id", "updated_at");
ALTER TABLE "launch_plans" ADD CONSTRAINT "launch_plans_org" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "launch_plans" ADD CONSTRAINT "launch_plans_project" FOREIGN KEY ("project_id", "organization_id") REFERENCES "research_projects"("id", "organization_id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "launch_plan_stages" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "launch_plan_id" TEXT NOT NULL, "stage" "LaunchStageKey" NOT NULL, "status" "LaunchStageStatus" NOT NULL DEFAULT 'NOT_STARTED', "dependencies" JSONB NOT NULL, "owner_label" TEXT, "due_date" TIMESTAMP(3), "budget" DECIMAL(18,4), "budget_currency" TEXT, "target_kpis" JSONB NOT NULL, "assumptions" JSONB NOT NULL, "risks" JSONB NOT NULL, "evidence_refs" JSONB NOT NULL, "updated_at" TIMESTAMP(3) NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "launch_plan_stages_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "launch_plan_stages_unique" ON "launch_plan_stages"("launch_plan_id", "stage"); CREATE INDEX "launch_plan_stages_status" ON "launch_plan_stages"("organization_id", "launch_plan_id", "status");
ALTER TABLE "launch_plan_stages" ADD CONSTRAINT "launch_plan_stages_org" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "launch_plan_stages" ADD CONSTRAINT "launch_plan_stages_plan" FOREIGN KEY ("launch_plan_id") REFERENCES "launch_plans"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "launch_plan_changes" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "launch_plan_id" TEXT NOT NULL, "stage" "LaunchStageKey", "action" TEXT NOT NULL, "details" JSONB NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "launch_plan_changes_pkey" PRIMARY KEY ("id"));
CREATE INDEX "launch_plan_changes_history" ON "launch_plan_changes"("organization_id", "launch_plan_id", "created_at");
ALTER TABLE "launch_plan_changes" ADD CONSTRAINT "launch_plan_changes_org" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "launch_plan_changes" ADD CONSTRAINT "launch_plan_changes_plan" FOREIGN KEY ("launch_plan_id") REFERENCES "launch_plans"("id") ON DELETE CASCADE ON UPDATE CASCADE;
